}

class InternalTeacher extends Teacher {}

class ExternalTeacher extends Teacher {}

class MasterStudent {}

class ExternalAuditor {}

class Room {}

Course "1" -- "*" Edition : offered in
Edition "1" *-- "*" Lesson : organized into
Lesson "*" -- "*" Teacher : given by
Course "1" -- "1" InternalTeacher : responsible
Teacher "0..*" -- "0..*" Course : assigned to
Lesson "*" -- "1" Room : assigned to
Lesson "*" -- "*" Resource : requires

Edition "1" -- "*" MasterStudent : enrolled
Edition "1" -- "*" ExternalAuditor : enrolled

@enduml

